import{clampInherit,meiosisState}from './inherit-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tx=(x,y,s,n=17)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f7f3ec" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;
const line=(d,c='#b7cecf',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
export const inheritSVG=(a,label)=>`<svg viewBox="0 0 560 410" role="img" aria-label="${esc(label)}">${a}</svg>`;
function chrom(x,y,type=0,copied=false,maternal=false){let c=maternal?'#e9ac98':'#b8d1d1',h=type?15:23;return(copied?line(`M${x-7} ${y-h}L${x+7} ${y+h}M${x+7} ${y-h}L${x-7} ${y+h}`,c,5):line(`M${x} ${y-h}V${y+h}`,c,6))+tx(x,y+h+16,type?'2':'1',11);}
function cell(x,y,r,contents,label=''){return`<circle cx="${x}" cy="${y}" r="${r}" fill="#345267" stroke="#a9c6c6" stroke-width="2"/>`+contents+(label?tx(x,y+r+24,label,14):'');}
export function meiosisFigure({progress=0}={}){let s=meiosisState(progress),a=tx(280,28,'One replication · two cell divisions',23),names=['Paired starting cell','Genetic information copied','After the first division','Four single-set products'];a+=tx(280,70,names[s.phase],20);let coords=s.cells===1?[[280,215]]:s.cells===2?[[160,215],[400,215]]:[[85,215],[215,215],[345,215],[475,215]],r=s.cells===1?90:s.cells===2?73:55;for(let[j,[x,y]]of coords.entries()){let c='';for(let i=0;i<s.chromosomesPerCell;i++)c+=chrom(x+(i-(s.chromosomesPerCell-1)/2)*25,y,i%2,s.copied,s.phase<2?i>=2:!!(j%2));a+=cell(x,y,r,c,s.phase===3?'Gamete '+(j+1):'');}a+=tx(280,337,s.phase===3?'2 chromosomes per product in this 4-chromosome example':'Joined copies are counted as one chromosome unit',16)+tx(280,373,'Final products differ genetically; variation mechanisms simplified',13)+tx(280,399,'Not all chromosome types shown · not four functional human eggs',12);return inheritSVG(a,'Meiosis summary. '+s.cells+' cell(s), '+s.chromosomesPerCell+' chromosome units per cell. '+names[s.phase]+'. Genetic differences are not fully drawn; colours/lengths mark types and source, not all variants.');}
export function fertilisationFigure({progress=0}={}){let p=clampInherit(progress),n=Math.min(3,Math.floor(p*4)),a=tx(280,29,'Combine sets, then grow by mitosis',23);if(n===0){let d=100*(1-p*4);a+=cell(280-d,210,65,chrom(270-d,210,0,false,false)+chrom(293-d,210,1,false,false),'Gamete: 2');a+=cell(280+d,210,65,chrom(270+d,210,0,false,true)+chrom(293+d,210,1,false,true),'Gamete: 2');}else{let coords=n===1?[[280,210]]:n===2?[[170,210],[390,210]]:[[175,160],[385,160],[175,290],[385,290]];for(let j=0;j<coords.length;j++){let[x,y]=coords[j];a+=cell(x,y,n===1?88:57,[0,1,2,3].map((v)=>chrom(x+(v-1.5)*20,y,v%2,false,v>=2)).join(''),n===1?'Zygote: 4':'4 per cell');}if(n===3)a+=tx(280,361,'Development also involves differentiation',16);}a+=tx(280,390,n<2?'Fertilisation restores the paired set':'Mitosis increases cells, preserving chromosome number',15);return inheritSVG(a,'Fertilisation: 2+2=4 chromosomes in a symbolic species. Subsequent mitotic daughters each retain4. Differentiation follows during development.');}
export function reproductionFigure({progress=0,asexual=false}={}){let p=clampInherit(progress),a=tx(280,35,asexual?'One parent · no gamete fusion':'Gamete fusion combines information',23);if(asexual){a+=cell(280,130,48,chrom(269,130,0)+chrom(292,130,1),'Parent');let count=1+Math.floor(p*3);for(let i=0;i<count;i++){let x=100+i*120;a+=line(`M280 195L${x} 250`)+cell(x,295,42,chrom(x-10,295,0)+chrom(x+12,295,1),'Clone');}a+=tx(280,390,'Mitosis normally preserves inherited genetic information',15);}else{let d=130*Math.max(0,1-p/.6);if(p<.6)a+=cell(280-d,160,55,chrom(270-d,160,0,false,false),'Male gamete')+cell(280+d,160,55,chrom(290+d,160,0,false,true),'Female gamete');if(p>=.6)a+=line('M280 235v25')+cell(280,265,62,chrom(266,315,0,false,false)+chrom(294,315,0,false,true),'Combined set');}return inheritSVG(a,asexual?'One parent makes genetically identical clones through mitosis.':'Male and female gametes combine genetic information. Cells, chromosome numbers and timing symbolic.');}
export function dnaFigure({state='',kind='dna'}={}){let a=tx(280,30,kind==='hierarchy'?'Genome → chromosome → DNA → gene':'Two DNA strands form a double helix',22);for(let i=0;i<20;i++){let y=85+i*12,t=i*.47,x1=280+Math.sin(t)*65,x2=280-Math.sin(t)*65;if(i<19){let yy=y+12;a+=line(`M${x1} ${y}L${280+Math.sin(t+.47)*65} ${yy}`,'#eab19c',4)+line(`M${x2} ${y}L${280-Math.sin(t+.47)*65} ${yy}`,'#bdd4d3',4);}a+=line(`M${x1} ${y}L${x2} ${y}`,i>=7&&i<=10?'#efce95':'#8ea7b1',i>=7&&i<=10?5:2);}a+=`<rect x="20" y="112" width="145" height="180" rx="20" fill="#345267" stroke="#bed0c9"/>`+tx(92,142,'Genome',16)+[0,1,2,3].map(i=>chrom(65+i%2*52,190+Math.floor(i/2)*48,i%2)).join('')+tx(92,317,'Whole collection',13)+line('M170 205h35');a+=line('M350 195h70')+tx(458,192,'Gene',17)+tx(280,350,'A section codes for an amino-acid sequence / protein',15)+tx(280,390,'Genome = entire genetic material · packaging not to scale',14);return inheritSVG(a,'DNA double helix, with highlighted gene section. Chromosomes contain DNA; genome is entire genetic material. Detailed bases/pairing are outside this shared overview.');}
export function evidenceFigure({kind='',state=''}={}){let rows=kind==='applications'?['Disease-linked genes','Inherited-disorder understanding and treatment','Past human migration patterns']:kind==='ledger'?['Body cell: paired set','Meiosis: single set','Fertilisation: paired set restored','Mitosis: chromosome number maintained']:kind==='plants'?['Pollen carries male gametes','Male gamete fuses with egg','Genetic information combines']:kind==='examples'?['Malaria: asexual in humans, sexual in mosquito','Fungi: asexual spores and sexual reproduction','Plants: sexual seeds; asexual runners / bulbs']:kind==='compare'?['Sexual: fusion of gametes and genetic mixing','Asexual: one parent, no fusion, clones','Meiosis forms gametes; mitosis preserves sets']:['Asexual: efficient without finding a mate','Sexual: inherited variation among offspring','Benefits depend on environmental conditions'];return inheritSVG(tx(280,35,kind==='applications'?'Why study human genomes?':'Compare the evidence',23)+rows.map((s,i)=>tx(280,115+i*65,s,16)).join('')+tx(280,390,'Original teaching schematic · use supplied context',13),'Evidence comparison. '+rows.join('. '));}
export function inheritFigure(o={}){if(o.concealed)return inheritSVG(tx(280,200,'Predict, then reveal the evidence',22),'Outcome concealed until prediction');if(['copy','divide','products','meiosis'].includes(o.kind))return meiosisFigure(o);if(['fusion','growth','differentiate','fertilisation'].includes(o.kind))return fertilisationFigure(o);if(o.kind==='sexual'||o.kind==='asexual')return reproductionFigure({...o,asexual:o.kind==='asexual'});if(['dna','gene','hierarchy'].includes(o.kind))return dnaFigure(o);return evidenceFigure(o);}
